import React, { useState, useEffect } from 'react';
import { useParams, useHistory } from 'react-router-dom';
import Header from '../../components/client/Header';
import Footer from '../../components/client/Footer';
import '../../styles/complaintDetail.css';

function ComplaintDetail() {
    const { id } = useParams();
    const history = useHistory();
    const [complaint, setComplaint] = useState(null);
    const [messages, setMessages] = useState([]);
    const [newMessage, setNewMessage] = useState('');
    const [loading, setLoading] = useState(true);
    const userId = localStorage.getItem('userId');

    useEffect(() => {
        if (!userId) {
            history.push('/login');
            return;
        }
        
        // Fetch complaint details
        fetch(`http://localhost:3001/complaint/${id}`)
            .then(res => res.json())
            .then(data => {
                if (data.error) {
                    alert(data.error);
                } else {
                    setComplaint(data);
                }
            })
            .catch(err => console.error('Erreur:', err));

        // Fetch complaint messages
        fetch(`http://localhost:3001/complaint/${id}/messages`)
            .then(res => res.json())
            .then(data => {
                setMessages(data);
                setLoading(false);
            })
            .catch(err => {
                console.error('Erreur messages:', err);
                setLoading(false);
            });
    }, [id, userId, history]);

    const handleSendMessage = (e) => {
        e.preventDefault();
        if (!newMessage.trim()) return;

        fetch(`http://localhost:3001/complaint/${id}/messages`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ idUser: userId, message: newMessage })
        })
        .then(res => res.json())
        .then(data => {
            if (data.error) {
                alert(data.error);
            } else {
                setNewMessage('');
                // Refresh messages
                fetch(`http://localhost:3001/complaint/${id}/messages`)
                    .then(res => res.json())
                    .then(msgData => setMessages(msgData));
            }
        })
        .catch(err => console.error('Erreur envoi message:', err));
    };

    if (loading) return <div className="complaint-detail-loading">Chargement...</div>;
    if (!complaint) return <div className="complaint-detail-error">Réclamation introuvable.</div>;

    return (
        <div className="home">
            <Header />
            <div className="container complaint-detail-container">
                <div className="complaint-detail-header">
                    <h2>Réclamation n°{complaint.idComplaint}</h2>
                    <div className={`complaint-state state-${complaint.state.replace(/\s+/g, '-').toLowerCase()}`}>
                        {complaint.state}
                    </div>
                </div>
                
                <div className="complaint-info-box">
                    <h3>{complaint.topic}</h3>
                    <p className="complaint-desc">{complaint.description}</p>
                    <p className="complaint-meta">Ouverte par {complaint.firstName} {complaint.lastName}</p>
                </div>

                <div className="complaint-messages-section">
                    <h3>Messages</h3>
                    <div className="messages-list">
                        {messages.length === 0 ? (
                            <p>Aucun message pour le moment.</p>
                        ) : (
                            messages.map(msg => {
                                const isCurrentUser = String(msg.idUser) === String(userId);
                                return (
                                    <div key={msg.idMessage} className={`message-item ${isCurrentUser ? 'message-right' : 'message-left'}`}>
                                        <div className="message-content">
                                            <p className="message-text">{msg.message}</p>
                                            <span className="message-author">
                                                {msg.firstName} {msg.lastName} {msg.role === 'admin' ? '(Admin)' : ''} - {new Date(msg.publishDate).toLocaleString('fr-FR')}
                                            </span>
                                        </div>
                                    </div>
                                );
                            })
                        )}
                    </div>

                    <form className="message-form" onSubmit={handleSendMessage}>
                        <textarea
                            value={newMessage}
                            onChange={(e) => setNewMessage(e.target.value)}
                            placeholder="Écrire un message..."
                            required
                            rows="4"
                            className="message-textarea"
                        ></textarea>
                        <button type="submit" className="btn-send-message">Envoyer</button>
                    </form>
                </div>
            </div>
            <Footer />
        </div>
    );
}

export default ComplaintDetail;
